// PLAN §9.2 step 4: kimi-k3 rewrites a seeded sample of generated training queries into natural
// phrasings while keeping every labeled phrase verbatim. Raw outputs are committed as source data in
// packages/datagen/paraphrases/ (LLM output can't be regenerated byte-identically); @qp/datagen
// re-derives labels by aligning the kept phrases, and drops anything that doesn't align.
// kimi-k3 is a different family from the test-set writers (Claude Haiku for v0, GLM for v1).
// Usage: node scripts/gen-paraphrases.mjs <train.jsonl> <n> <out.jsonl>
import { readFileSync, writeFileSync } from "node:fs"
import { chat, model } from "../spikes/S04-time/llm.mjs"

const [input, nArg, output] = process.argv.slice(2)
const n = Number(nArg ?? 6000)

function mulberry32(a) {
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const rows = readFileSync(input, "utf8")
  .split("\n")
  .filter(Boolean)
  .map((l, line) => ({ line, ...JSON.parse(l) }))
const spansOf = (r) => {
  const out = []
  r.tags.forEach((t, i) => {
    if (t.startsWith("B-")) out.push({ role: t.slice(2), from: i, to: i })
    else if (t.startsWith("I-") && out.length) out[out.length - 1].to = i
  })
  return out.map((s) => ({
    role: s.role,
    text: r.text.slice(r.offsets[s.from][0], r.offsets[s.to][1]),
  }))
}
// Positives with at least two labeled phrases; negatives don't need paraphrasing.
const pool = rows.filter((r) => !r.source.startsWith("template:none") && spansOf(r).length >= 2)
const rand = mulberry32(4242)
for (let i = pool.length - 1; i > 0; i--) {
  const j = Math.floor(rand() * (i + 1))
  ;[pool[i], pool[j]] = [pool[j], pool[i]]
}
const sample = pool.slice(0, n)

const batches = []
for (let i = 0; i < sample.length; i += 25) batches.push(sample.slice(i, i + 25))

async function run(batch) {
  const lines = batch.map((r, k) => {
    const keep = spansOf(r)
      .map((s) => `"${s.text}"`)
      .join(", ")
    return `${k}\t${r.text}\tkeep: ${keep}`
  })
  const prompt = `Below are search queries typed into a workplace search box (chat, email, docs, tickets). Rewrite each one the way a real, busy person would type it: reorder words, drop or add small words, use shorthand, questions, or a different but natural structure. Vary the style across the batch.

Rules:
- Keep every phrase listed after "keep:" exactly as written (same words, same spelling), each exactly once.
- Keep the meaning: who did what, and what is being looked for, must not change ("from priya" must still mean priya sent or wrote it).
- Add no new names, dates, places, file types or states.

Output one JSON object per line: {"i": <index>, "text": "<rewrite>"}. Nothing else.

${lines.join("\n")}`
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const out = await chat(prompt, { temperature: 1, maxTokens: 24000 })
      return out
        .split("\n")
        .filter((l) => l.trim().startsWith("{"))
        .map((l) => JSON.parse(l))
    } catch (e) {
      if (attempt === 2) {
        console.error(String(e).slice(0, 200))
        return []
      }
    }
  }
}

const results = []
const CONCURRENCY = 8
let next = 0
await Promise.all(
  Array.from({ length: CONCURRENCY }, async () => {
    while (next < batches.length) {
      const b = batches[next++]
      const got = await run(b)
      for (const g of got) {
        const r = b[g.i]
        if (r && typeof g.text === "string")
          results.push({
            line: r.line,
            source: r.source,
            seed: r.seed,
            text: r.text,
            spans: spansOf(r),
            paraphrase: g.text,
          })
      }
      if (results.length % 500 < 25) console.error(`${results.length} paraphrases`)
    }
  }),
)
results.sort((a, b) => a.line - b.line)
writeFileSync(output, `${results.map((r) => JSON.stringify(r)).join("\n")}\n`)
console.log(`${model}: ${results.length} paraphrases of ${sample.length} sampled queries`)
